 chips:[['Todas',()=>1],['Por enviar',r=>r.estado=='Pendiente'&&r.dir=='Enviadas'],['Esperando respuesta',r=>['Enviada','Recibida'].includes(r.estado)&&r.dir=='Enviadas'],['Recibidas por anotar',r=>r.dir=='Recibidas'&&r.estado=='Recibida'],['Observadas',r=>r.estado=='Observada'],['Confirmadas',r=>r.estado=='Confirmada']],
 tabs:r=>[[r.lote?'Candidatos':'Contrayente',()=>`${r.lote?`<p class="sm muted">Lote: una notificación por parroquia de bautismo. Se marca cada candidato (completa o parcial).</p>`:''}<div class="pn">${r.lista.map((c,i)=>`<div class="li"><span class="x"><b style="font-weight:600">${esc(c.n)}</b><small>Bautismo: ${esc(c.bp)}</small></span>${r.dir=='Recibidas'&&r.estado=='Recibida'?`<select aria-label="Anotación de ${esc(c.n)}" onchange="nmMarca('${r.id}',${i},this.value)"><option value="">Sin marcar</option>${['Completa','Parcial'].map(x=>`<option ${x==c.marca?'selected':''}>${x}</option>`).join('')}</select>`:c.marca?sb(c.marca):''}</div>`).join('')}</div>`],
  ['Seguimiento',()=>`<div class="stp">${NMP.map((s,i)=>`<span class="${NMP.indexOf(r.estado)>i?'ok':r.estado==s?'on':''}">${NMP.indexOf(r.estado)>i?'✓ ':''}${s}</span>`).join('')}</div>${r.resp?`<div class="esum" role="alert">${I('warn')}<span><b>Respuesta con observación: ${esc(r.resp.tipo)}.</b> ${esc(r.resp.obs)}</span></div>`:''}${r.anotada?`<div class="info">${I('check')}<span>Anotada en el libro físico el ${r.anotada}${r.foto?' · foto: '+esc(r.foto):''}.</span></div>`:''}<div class="kv"><span>Recordatorio automático</span><b>a los 15 días sin respuesta</b></div><div class="kv"><span>Alerta a la curia</span><b>${nmDias(r)>30&&r.estado!='Confirmada'?'Sí (más de 30 días)':'No'}</b></div><div class="kv"><span>Expediente</span><b>${r.estado=='Confirmada'?'Cerrado':'Se cierra solo con la confirmación'}</b></div>`]],
