  if(r.dir=='Enviadas'&&['Enviada','Recibida'].includes(r.estado))b.push(`<button class="btn" onclick="nmRec('${r.id}')">${I('bell')}Recordar</button><button class="btn p" onclick="nmSimConf('${r.id}')">Simular confirmación</button>`);
