function vNmarg(){const N=DB.nmarg;const k=(t,v,c)=>`<div><small>${t}</small><b>${v}</b><div class="tr"><span class="${c||''}">${c=='dn'&&v?'Requiere atención':'&nbsp;'}</span></div></div>`;
 return ph('Notificaciones marginales','Confirmación y matrimonio hacia la parroquia del bautismo. Ordenadas por antigüedad.',`<button class="btn hm" onclick="exportar('Notificaciones marginales')">${I('dl')}Exportar</button>`)
 +`<div class="kp">${k('Por enviar',N.filter(r=>r.estado=='Pendiente'&&r.dir=='Enviadas').length)}${k('Sin respuesta +15 días',N.filter(r=>r.dir=='Enviadas'&&['Enviada','Recibida'].includes(r.estado)&&nmDias(r)>15).length,'dn')}${k('Recibidas por anotar',N.filter(r=>r.dir=='Recibidas'&&r.estado=='Recibida').length)}${k('Observadas',N.filter(r=>r.estado=='Observada').length,'dn')}</div>`
 +`<div class="info">${I('help')}<span><b>Misma parroquia:</b> tarea interna; se anota en el libro y se adjunta foto. <b>Otra parroquia con el sistema:</b> notificación digital firmada; «Anotado» equivale al sello. <b>Sin el sistema:</b> PDF firmado con QR por correo o WhatsApp, con página para confirmar sin cuenta.</span></div>`
 +table('nmarg',{ent:'nmarg',rows:()=>[...DB.nmarg].sort((a,b)=>nmDias(b)-nmDias(a)),cols:E.nmarg.cols,chips:E.nmarg.chips,ph:'Buscar por nombre, parroquia o referencia…',empty:['No hay notificaciones','Se crean solas al cerrar una confirmación o un matrimonio.']})}
const nmR=id=>DB.nmarg.find(x=>x.id==id);
function nmUp(id,msg,fn,acc){const r=nmR(id);commit(msg,()=>{fn(r);hist(r,acc)},{acc,ent:'Notificaciones marginales',obj:r.ref},{keep:1});setTimeout(()=>det('nmarg',id,1),20)}
function nmMarca(id,i,v){const r=nmR(id);r.lista[i].marca=v;save()}
function nmEnviar(id){const r=nmR(id);ask({t:'Enviar notificación',txt:esc(r.ref)+' · '+esc(r.destino),html:r.modo.startsWith('Digital')?`<div class="info">${I('send')}<span>${esc(r.destino)} usa el sistema: llegará firmada a su bandeja.</span></div>`:`<div class="fld"><span>Canal</span><div class="seg" role="radiogroup"><button type="button" class="on" onclick="$$('#md2 .seg button').forEach(b=>b.classList.remove('on'));this.classList.add('on')">Correo</button><button type="button" onclick="$$('#md2 .seg button').forEach(b=>b.classList.remove('on'));this.classList.add('on')">WhatsApp</button><button type="button" onclick="$$('#md2 .seg button').forEach(b=>b.classList.remove('on'));this.classList.add('on')">Físico con seguimiento</button></div><div class="fh">Contacto tomado del directorio diocesano.</div></div>`,ok:'Enviar',undo:false,onok:()=>nmUp(id,'Notificación enviada',r=>{r.estado='Enviada';r.enviada=HOY},'Envió la notificación')})}
function nmRec(id){nmUp(id,'Recordatorio enviado a '+nmR(id).destino,()=>{},'Envió recordatorio')}
function nmSimConf(id){nmUp(id,'Simulado: la otra parroquia confirmó la anotación',r=>{r.estado='Confirmada';r.anotada=HOY;r.lista.forEach(c=>c.marca=c.marca||'Completa')},'La parroquia de bautismo confirmó la anotación')}
function nmReenv(id){nmUp(id,'Notificación corregida y reenviada',r=>{r.estado='Enviada';r.enviada=HOY;delete r.resp},'Corrigió y reenvió')}
function nmAnotar(id){const r=nmR(id);ask({t:'Registrar anotación en el libro físico',txt:esc(r.ref),html:`<div class="fld"><label class="fl" for="nm_f">Fecha real de la anotación <span class="req">(obligatorio)</span></label><input id="nm_f" value="${HOY}" placeholder="dd/mm/aaaa"></div><div class="fld"><span>Foto de la nota marginal</span><button type="button" class="btn" onclick="this.outerHTML='${esc(tagE('nota_marginal.jpg'))}'">${I('up')}Adjuntar foto</button></div>`,ok:'Marcar como anotado',onok:()=>{const f=$('#nm_f')?.value||HOY;nmUp(id,'Anotación registrada: '+r.ref,r=>{r.anotada=f;r.foto='nota_marginal.jpg';r.estado=r.modo=='Misma parroquia'||r.dir=='Recibidas'?'Confirmada':'Anotada';r.lista.forEach(c=>c.marca=c.marca||'Completa')},'Registró la anotación del '+f)}})}
function nmObs(id){ask({t:'Responder con observación',txt:esc(nmR(id).ref),html:`<div class="fld"><label class="fl" for="nm_t">Observación</label><select id="nm_t"><option>No se encontró</option><option>No coincide</option><option>Datos incompletos</option></select></div>`,motivo:'Detalle para la otra parroquia',ok:'Enviar respuesta',onok:m=>{const t=$('#nm_t')?.value||'No coincide';nmUp(id,'Respuesta enviada con observación',r=>{r.estado='Observada';r.resp={tipo:t,obs:m}},'Respondió: '+t)}})}
function nmPdf(id){const r=nmR(id);preview('Notificación marginal (PDF con QR)',paperHead('NOTIFICACIÓN DE '+r.tipo.toUpperCase()+' PARA ANOTACIÓN MARGINAL',esc(r.ref))+`<p style="font-family:var(--sans)">Se ruega anotar al margen del acta de bautismo de:</p><table style="font-family:var(--sans)"><tbody>${r.lista.map(c=>`<tr><td>${esc(c.n)}</td><td>Bautismo ${esc(c.bp)}</td></tr>`).join('')}</tbody></table><div class="rcb"><p style="font-family:var(--sans);font-size:.88rem">Para confirmar sin crear cuenta, escanee el QR y pulse «Confirmar anotación» (quién, fecha y foto). También puede imprimir, sellar y devolver escaneado.</p><div class="c">${qr('nm'+r.id,104)}<small>verifica.diocesis.pe</small></div></div>${seal()}`,{btns:`<button class="btn" onclick="nmPagina('${r.id}')">${I('eye')}Página sin cuenta</button>`})}
function nmPagina(id){const r=nmR(id);preview('verifica.diocesis.pe · Confirmar anotación',`<div style="font-family:var(--sans)"><p class="sm muted">Página pública, sin cuenta. Diócesis de San Ejemplo.</p><h2 style="font:400 1.3rem var(--serif)">Confirmar anotación marginal</h2><p>${esc(r.ref)}</p><div class="fg"><div class="fld"><span>Su nombre</span><input></div><div class="fld"><span>Fecha de anotación</span><input placeholder="dd/mm/aaaa"></div></div><div class="drop">${I('up')}<p>Foto de la nota marginal</p></div><button class="btn p mt" onclick="nmSimConf('${r.id}')">Confirmar anotación</button><p class="sm muted mt">Al confirmar, su parroquia puede sumarse al sistema gratis para recibir estas notificaciones en línea.</p></div>`)}

