 defaults:()=>({tipo:'Licencia matrimonial',formato:'Físico',fecha:HOY,num:'LIC-2026-0'+(21+DB.licpar.length)}),onCreate:r=>{r.estado='Emitida sin enviar';r.dir='Emitidas';r.de='San José'},
