function lpPrint(id){const r=DB.licpar.find(x=>x.id==id);preview(r.num,paperHead(r.tipo.toUpperCase(),'N.º '+esc(r.num))+`<p style="font-family:var(--serif);font-size:1.05rem;line-height:1.7">El suscrito párroco de ${esc(r.de)} concede licencia para que <b>${esc(r.persona)}</b> realicen el trámite en la parroquia ${esc(r.para)}, habiéndose concluido el expediente correspondiente.</p><p style="font-family:var(--sans);font-size:.88rem">Devolver esta licencia anotada a la parroquia de origen.</p><div class="rcb"><div class="sig" style="flex:1"><div>Párroco</div></div><div class="c">${qr('lic'+r.num,96)}<small>verifica.diocesis.pe</small></div></div>${seal()}`)}

