const CXH=['NOMBRE COMPLETO','F. BAUTISMO','LIBRO','FOLIO','PARTIDA','PADRES','PADRINOS','MINISTRO'];
const CXF=['Bautizado(a)','Fecha','Libro','Folio','Número de acta','Padres','Padrinos','Ministro','(no cargar)'];
function cxRows(){return [['Rosa María Lazo Quispe','12/04/1998','IX','10','37','Ángel Lazo · Ana Quispe','Pío Lazo · Inés Ruiz','P. Julio Ugarte'],['Juan Pablo Soto Ríos','31/02/1998','IX','10','38','Luis Soto · Eva Ríos','Raúl Ríos','P. Julio Ugarte'],['','19/04/1998','IX','10','39','Hugo Pérez · Rita Paz','Elsa Paz','P. Julio Ugarte'],['Lucía Torres Mena','26/04/1998','IX','11','40','Abel Torres · Nora Mena','Iván Mena · Sara Mena','P. Julio Ugarte'],['Marco Antonio Díaz','26/04/1998','IX','11','40','José Díaz · Clara Ruiz','Teo Ruiz','P. Julio Ugarte'],['Diego Armando Paredes Vega','14/06/1987','XI','112','410','Armando Paredes · Vilma Vega','Carlos Vega Ríos','P. Julio Ugarte'],['Elena Campos Ruiz','03/05/1998','IX','11','41','Raúl Campos · Ida Ruiz','Ana Ruiz','P. Julio Ugarte'],['Tomás Ugaz León','10/05/1998','IX','11','42','Pedro Ugaz · Rosa León','Luis León','P. Julio Ugarte']].map(c=>({c,ok:1}))}
function cxVal(r){const libs={};return r.rows.map((x,i)=>{const [n,f,l,fo,a]=x.c;const e=[];if(!n)e.push('Falta el nombre');const m=/^(\d\d)\/(\d\d)\/(\d{4})$/.exec(f||'');if(!m||+m[1]>31||+m[2]>12||(+m[2]==2&&+m[1]>29))e.push('Fecha inválida');const k=l+'·'+fo+'·'+a;if(libs[k]!=null)e.push(`Duplicado con la fila ${libs[k]+1} (libro/folio/acta)`);else libs[k]=i;if(DB.actas.some(y=>libFrom(y.libro)?.num==l&&y.folio==+fo&&y.num==+a))e.push('El acta ya existe en el sistema');return e})}
