const MPOLY={sj:[[60,60],[300,40],[330,220],[120,250]],sr:[[300,40],[560,60],[540,200],[330,220]],nsg:[[330,220],[540,200],[560,330],[380,360]],sp:[[380,360],[560,330],[580,460],[400,470]],sm:[[120,250],[330,220],[380,360],[400,470],[90,440]],ca:[[560,60],[740,90],[760,300],[560,330],[540,200]]};
const MPT={sj:[190,140],sr:[440,120],nsg:[450,280],sm:[230,350],ca:[650,190]};
const MCAP=[['Capilla Santa Rosa de Lima','sj',[110,200]],['Capilla San Judas Tadeo','sm',[170,420]],['Capilla de Guadalupe','nsg',[500,250]],['Capilla San Pablo','nsg',[490,420]]];
const MCOL=[['Colegio Santa Ana','ca',[700,250]],['Casa de las Hnas. Franciscanas','sr',[380,80]],['Colegio San José Obrero','sj',[250,90]]];
const MDIR={'jr. junín 455, breña':[420,120],'av. grau 1020, lima':[200,150],'calle real 88, lima':[450,300],'psje. las flores 9, rímac':[220,380],'av. brasil 1501, breña':[690,140]};
