let MP={y:2026,par:1,cap:1,ter:1,agr:1,col:0,ind:'Agrupación',pin:null,q:'',pub:0};
function terr(id,y){if(id=='sp')return y>=2020?'nsg':'sm';if(id=='nsg')return y>=2015?'nsg':'sr';return id}
function pip(p,poly){let c=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [xi,yi]=poly[i],[xj,yj]=poly[j];if(((yi>p[1])!=(yj>p[1]))&&(p[0]<(xj-xi)*(p[1]-yi)/(yj-yi)+xi))c=!c}return c}
function mpDonde(pt){for(const k in MPOLY)if(pip(pt,MPOLY[k]))return terr(k,MP.y);return null}
function mpColor(id){const p=DB.parroquias.find(x=>x.id==id);if(MP.ind=='Aportes a la curia')return {Pagado:'#a9c9ae',Pendiente:'#e7cf94',Vencido:'#e2a6a6'}[p.aporte]||'#ddd';if(MP.ind=='Estadística del trimestre'){const e=DB.com.find(c=>c.id=='cm1').est[id];return {'A tiempo':'#a9c9ae',Pendiente:'#e7cf94','Con retraso':'#efc08f',Vencido:'#e2a6a6'}[e]||'#ddd'}return MP.agr?DCOL[p.decanato]||'#ddd':'#e9e4da'}
function mpSet(k,v){MP[k]=v;render()}
function mpBuscar(){const q=($('#mp_q')?.value||'').trim();MP.q=q;if(!q){MP.pin=null;MP.err='Escriba una dirección, por ejemplo: Jr. Junín 455, Breña.';return render()}MP.err='';const k=norm(q);const hit=Object.keys(MDIR).find(a=>norm(a).startsWith(k.slice(0,8)));MP.pin=hit?MDIR[hit]:[100+hash(q).charCodeAt(0)%6*100,90+hash(q).charCodeAt(1)%5*80];render()}
function vMapa(){const y=MP.y;const ids=Object.keys(MPOLY);const P=id=>DB.parroquias.find(x=>x.id==id);const cur=MP.pin&&mpDonde(MP.pin);const pc=cur&&P(cur);const cu=isCuria();
 const svg=`<svg class="map" viewBox="0 0 800 500" role="img" aria-label="Mapa ficticio de parroquias y territorios de la diócesis en ${y}"><rect width="800" height="500" fill="#f4f1ea"/><path d="M0 470 C200 440 400 500 800 455 L800 500 L0 500Z" fill="#cfe0e6"/><path d="M40 0 L780 480" stroke="#e2dccf" stroke-width="10"/><path d="M0 300 L800 250" stroke="#e2dccf" stroke-width="8"/>
 ${MP.ter?ids.map(k=>{const o=terr(k,y);return `<polygon points="${MPOLY[k].map(p=>p.join(',')).join(' ')}" fill="${mpColor(o)}" fill-opacity=".75" stroke="#fff" stroke-width="3"/>`}).join(''):''}
 ${MP.ter?ids.filter(k=>k!='sp'&&!(k=='nsg'&&y<2015)).map(k=>{const t=MPT[k];return `<text x="${t[0]}" y="${t[1]+30}" text-anchor="middle" class="ml">${esc(P(k).nombre)}</text>`}).join(''):''}
 ${MP.par?ids.filter(k=>MPT[k]&&!(k=='nsg'&&y<2015)).map(k=>{const t=MPT[k];return `<g><circle cx="${t[0]}" cy="${t[1]}" r="9" fill="#7a2f3a" stroke="#fff" stroke-width="2"/><path d="M${t[0]} ${t[1]-5}v10M${t[0]-4} ${t[1]-1}h8" stroke="#fff" stroke-width="2"/></g>`}).join(''):''}
 ${MP.cap?MCAP.filter(c=>!(c[0]=='Capilla San Pablo'&&y<2000)).map(c=>`<rect x="${c[2][0]-6}" y="${c[2][1]-6}" width="12" height="12" rx="2" fill="#fff" stroke="#7a2f3a" stroke-width="2"/>`).join(''):''}
 ${MP.col?MCOL.map(c=>`<path d="M${c[2][0]} ${c[2][1]-8}l8 8-8 8-8-8z" fill="#4a5d8a" stroke="#fff" stroke-width="2"/>`).join(''):''}
 ${MP.pin?`<g><path d="M${MP.pin[0]} ${MP.pin[1]}c-10-14-14-20-14-27a14 14 0 0 1 28 0c0 7-4 13-14 27z" fill="#1f1b18"/><circle cx="${MP.pin[0]}" cy="${MP.pin[1]-27}" r="5" fill="#fff"/></g>`:''}</svg>`;
 const leg=MP.ind=='Agrupación'||!cu?Object.entries(DCOL).map(([k,c])=>`<span><i style="background:${c}"></i>${k}</span>`).join(''):MP.ind=='Aportes a la curia'?[['Pagado','#a9c9ae'],['Pendiente','#e7cf94'],['Vencido','#e2a6a6']].map(([k,c])=>`<span><i style="background:${c}"></i>${k}</span>`).join(''):[['A tiempo','#a9c9ae'],['Pendiente','#e7cf94'],['Con retraso','#efc08f'],['Vencido','#e2a6a6']].map(([k,c])=>`<span><i style="background:${c}"></i>${k}</span>`).join('');
 const ly=[['par','Parroquias'],['cap','Capillas'],['ter','Territorios'],['agr','Agrupaciones'],['col','Colegios y casas religiosas']];
 return ph('Mapa de la diócesis','Mapa ficticio de demostración. En producción: MapLibre u OpenStreetMap.',`${cu?`<button class="btn" onclick="ask({t:'Editar límites del territorio',txt:'Solo el administrador diocesano, con decreto. Cada cambio crea una nueva versión del territorio con fecha.',motivo:'N.º de decreto y motivo',ok:'Abrir editor (simulado)',onok:m=>toast('Editor de límites abierto (simulado). Decreto: '+m)})">${I('edit')}Editar límites</button>`:''}<button class="btn" onclick="mpSet('pub',${MP.pub?0:1})">${I('eye')}${MP.pub?'Ver versión interna':'Ver versión pública'}</button>`)
 +`<div class="mapw"><div class="pn mapc">${svg}<div class="leg pad">${leg}<span><i class="sq"></i>Capilla</span>${MP.col?'<span><i class="dm"></i>Colegio o casa religiosa</span>':''}</div></div>
 <div class="mside"><div class="pn pad"><h3 class="h4" style="margin-top:0">¿Dónde estoy?</h3><div class="fld"><label class="fl" for="mp_q">Dirección</label><input id="mp_q" value="${esc(MP.q)}" placeholder="Ej.: Jr. Junín 455, Breña" ${MP.err?'aria-invalid="true"':''} onkeydown="if(event.key=='Enter')mpBuscar()">${MP.err?`<div class="fe" role="alert">${I('warn')}${MP.err}</div>`:''}</div><div class="row"><button class="btn p" onclick="mpBuscar()">${I('srch')}Buscar</button><button class="btn" onclick="MP.q='Mi ubicación';MP.err='';MP.pin=[480,410];render()">${I('pin')}Usar mi ubicación</button></div>
 ${pc?`<div class="mres"><small>Le corresponde ${y<2026?'(en '+y+')':''}</small><b>Parroquia ${esc(pc.nombre)}</b>${MP.pub&&!cu?'':`<div class="kv"><span>Párroco</span><b>${esc(pc.parroco)}</b></div>`}<div class="kv"><span>Misas</span><b>Dom 7:00, 10:00, 19:00</b></div><div class="kv"><span>Teléfono</span><b>01 426 00${10+DB.parroquias.indexOf(pc)}</b></div><div class="row mt"><button class="btn" onclick="toast('Se abrió Google Maps con la ruta (simulado).')">${I('pin')}Cómo llegar · Google Maps</button><button class="btn" onclick="toast('Se abrió Waze con la ruta (simulado).')">Waze</button></div></div>`:MP.pin?'<p class="sm muted">Esa ubicación está fuera de los territorios.</p>':''}</div>
 <div class="pn pad"><div class="fld"><label class="fl" for="mp_y">Ver el mapa en el año: <b>${y}</b></label><input id="mp_y" type="range" min="1990" max="2026" value="${y}" oninput="MP.y=+this.value;this.previousElementSibling.querySelector('b').textContent=this.value" onchange="mpSet('y',+this.value)"><div class="fh">Antes de 2015, Guadalupe era capilla de Santa Rosa. En 2020 se le sumó el sector San Pablo.</div></div>
 <fieldset class="lay"><legend>Capas</legend>${ly.map(([k,l])=>`<label class="ckr"><input type="checkbox" ${MP[k]?'checked':''} onchange="mpSet('${k}',this.checked?1:0)"><span>${l}</span></label>`).join('')}</fieldset>
 ${cu?`<div class="fld"><label class="fl" for="mp_i">Colorear según</label><select id="mp_i" onchange="mpSet('ind',this.value)">${['Agrupación','Aportes a la curia','Estadística del trimestre'].map(x=>`<option ${x==MP.ind?'selected':''}>${x}</option>`).join('')}</select></div>`:''}</div></div></div>`}

