 title:r=>r.tipo+' · '+r.par,status:r=>r.estado,sub2:r=>esc(r.ref),
 cols:[col('Tipo','tipo',{f:r=>esc(r.tipo)+`<small class="muted" style="display:block">${esc(r.sub)}</small>`}),col('Parroquia','par',{key:1}),col('Vinculado a','ref',{c:'hm'}),col('Antigüedad','d',{s:apDias,f:r=>`${apDias(r)} días${apDias(r)>15&&!['Aprobada','Rechazada'].includes(r.estado)?' '+bd('Plazo vencido','ac'):''}`}),col('Estado','estado',{f:r=>sb(r.estado)})],
